const CheckNudge = "Checks failed on PR %s for %s: %s. Read each failure's log, handle it as your build skill's step 7 says, and push."

type Action struct {
    // ...existing...
    // Checks are the failed checks a ReasonCheck Nudge reports. The executor
    // records them once the Prompt lands.
    Checks []pullrequest.CheckID
}

